export const dictionaries={my:new Map(),zh:new Map()};
export function register(en,my,zh){if(en){dictionaries.my.set(en.trim().replace(/\s+/g,' ').toLowerCase(),my);dictionaries.zh.set(en.trim().replace(/\s+/g,' ').toLowerCase(),zh);}}
[...rows,...headings].forEach(r=>register(...r));names.en.forEach((n,i)=>register(n,names.my[i],names.zh[i]));facts('en').forEach((f,i)=>f.forEach((v,j)=>register(v,facts('my')[i][j],facts('zh')[i][j])));
descriptions.forEach((text,i)=>register(text,overviews.my[i],overviews.zh[i]));
export let language='en';try{const saved=localStorage.getItem('orbit-language');if(codes.includes(saved))language=saved;}catch{}
export function translate(text,lang=language){if(lang==='en')return text;const key=text.trim().replace(/\s+/g,' '),map=dictionaries[lang];const value=map.get(key.toLowerCase());if(value)return text.replace(text.trim(),value);if(key.includes(' / '))return key.split(' / ').map(part=>translate(part,lang)).join(' / ');const numbered=key.match(/^((?:\d+|0\d)\s*[\/—]\s*)(.+)$/);if(numbered){const tail=translate(numbered[2],lang);if(tail!==numbered[2])return numbered[1]+tail;}for(const mark of [' ↗',' · 3D OBSERVATION',': a closer look']){if(key.endsWith(mark)){const base=key.slice(0,-mark.length),result=translate(base,lang);if(result!==base)return result+(mark===': a closer look'?(lang==='my'?'ကို ပိုမိုလေ့လာရန်':'：深入了解'):mark===' · 3D OBSERVATION'?' · '+translate('3D OBSERVATION',lang):mark);}}const next=key.match(/^Next (planet|destination): (.+) ↗$/);if(next)return (lang==='my'?'နောက်တစ်ခု: ':'下一站：')+translate(next[2],lang)+' ↗';const metric=key.match(/^([~\d.,]+) (million km|days|years)$/);if(metric)return metric[1]+' '+({my:{'million km':'သန်းကီလိုမီတာ',days:'ရက်',years:'နှစ်'},zh:{'million km':'百万公里',days:'天',years:'年'}}[lang][metric[2]]);return text;}
const originals=new WeakMap(),attributes=new WeakMap();let observer,pending=false;
function ignored(el){return el?.closest('script,style,canvas,code,kbd,[data-no-translate],#language-control,#space-guide,#guide-toggle');}
function apply(){if(!document.body)return;observer?.disconnect();const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let n;while(n=walker.nextNode()){if(!n.textContent.trim()||ignored(n.parentElement))continue;const old=originals.get(n);const original=old&&n.textContent===old.translated?old.original:n.textContent;const translated=translate(original);if(n.textContent!==translated)n.textContent=translated;originals.set(n,{original,translated});}for(const el of document.querySelectorAll('[aria-label],[placeholder],[title]')){if(ignored(el))continue;let record=attributes.get(el)||{};for(const attr of ['aria-label','placeholder','title']){if(!el.hasAttribute(attr))continue;const current=el.getAttribute(attr),old=record[attr],original=old&&current===old.translated?old.original:current,translated=translate(original);if(current!==translated)el.setAttribute(attr,translated);record[attr]={original,translated};}attributes.set(el,record);}document.documentElement.lang=language==='zh'?'zh-Hans':language;document.body.dataset.language=language;const select=document.getElementById('site-language');if(select)select.value=language;const note=document.getElementById('language-note');if(note){note.hidden=language==='en';note.textContent=language==='my'?'အဓိကထိန်းချုပ်မှုများ၊ ဂြိုဟ်အချက်အလက်များနှင့် မေးဖြေကို ဘာသာပြန်ထားပါသည်။ အချို့အသေးစိတ်ဆောင်းပါးများမှာ အင်္ဂလိပ်ဘာသာဖြင့် ဖြစ်နေဆဲပါ။':'主要操作、行星知识和问答已翻译。部分详细任务文章仍为英文。';}observer?.observe(document.body,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['aria-label','placeholder','title']});}
export function setLanguage(value){if(!codes.includes(value))return;language=value;try{localStorage.setItem('orbit-language',value);}catch{}apply();window.dispatchEvent(new CustomEvent('orbit-language-change',{detail:value}));}
function init(){const header=document.getElementById('site-header');if(header){const control=document.createElement('label');control.id='language-control';control.innerHTML='<span aria-hidden="true">◎</span><span class="sr-only">Language / ဘာသာစကား / 语言</span><select id="site-language" aria-label="Language / ဘာသာစကား / 语言"><option value="en">English</option><option value="my">မြန်မာ</option><option value="zh">简体中文</option></select>';header.insertBefore(control,document.getElementById('nav-toggle'));control.querySelector('select').onchange=e=>setLanguage(e.target.value);const note=document.createElement('p');note.id='language-note';note.setAttribute('data-no-translate','');header.after(note);}observer=new MutationObserver(()=>{if(!pending){pending=true;requestAnimationFrame(()=>{pending=false;apply();});}});apply();}
// Read-only exported data is also used by the question guide.
export {names,overviews};
if(typeof document!=='undefined'){if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();}
